import typing
import logging

from jsilib.aio import interface as aio_interface
from jsilib.transport import interface as transport_interface, exc as transport_exc
from jsilib.base import IClosable

from . import _globals

logger = logging.getLogger(_globals.LOGGER_NAME)


class FrameReader(IClosable):
    # TODO: This class is already tested via functional tests, but a separate
    # unit test suite would be appreciated here.

    # TODO: Use this class inside JSIConnection class.

    FrameType = typing.Type[transport_interface.Frame]
    FrameHandlerFunc = typing.Callable[[transport_interface.Frame], bool]
    ConnectionClosedHandlerFunc = typing.Callable[[], None]

    def __init__(self,
                 reactor: aio_interface.IReactor,
                 transport_connection: transport_interface.ITransportConnection):
        self._reactor = reactor
        self._transport_connection = transport_connection
        self._frame_handlers = {}
        self._connection_closed_handler = None
        self._closed = False
        self._task = None

    def start(self):
        if self._task is None:
            self._task = self._reactor.run(self._run())

    def register_frame_handler(self, frame_type: FrameType, func: FrameHandlerFunc):
        self._frame_handlers[frame_type] = func

    def register_connection_closed_handler(self, func: ConnectionClosedHandlerFunc):
        self._connection_closed_handler = func

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            if self._task is not None:
                await self._task.cancel()

    async def _run(self):
        while not self._closed and not self._transport_connection.is_closed():
            try:
                frame = await self._transport_connection.recv()
            except transport_exc.ConnectionClosedError:
                logger.debug('Transport was closed - closing FrameReader on this end...')
                self._closed = True
                if self._connection_closed_handler is not None:
                    self._connection_closed_handler()
                break
            frame_handler = self._frame_handlers.get(frame.__class__)
            if frame_handler is None:
                logger.warning('Ignoring incoming frame, as no handler registered that could handle it: %r', frame)
                continue
            try:
                handled = frame_handler(frame)
                if not handled:
                    logger.warning('Ignoring incoming frame, as the handler refused to handle it: %r', frame)
            except:
                logger.error('An exception occurred during incoming frame handling:', exc_info=True)
